'use strict';

const TopHairCollections = {
  cart: [],
  config: {
    currency: '₦',
    whatsappNumber: '2347031696283',
    paystackUrl: 'https://paystack.com/pay/',
    storageKey: 'topHairCart'
  },
  init() {
    this.loadCartFromStorage();
    this.displayCart();
    this.setupSearchListeners();
  },
  loadCartFromStorage() {
    try {
      const saved = localStorage.getItem(this.config.storageKey);
      if (saved) this.cart = JSON.parse(saved);
    } catch (e) {
      console.error('Error loading cart:', e);
    }
  },
  saveCartToStorage() {
    try {
      localStorage.setItem(this.config.storageKey, JSON.stringify(this.cart));
    } catch (e) {
      console.error('Error saving cart:', e);
    }
  },
  setupSearchListeners() {
    const searchInput = document.getElementById('productSearch');
    if (searchInput) {
      searchInput.addEventListener('keyup', function (e) {
        if (e.key === 'Enter') performSearch();
      });
    }
  }
};

function addToCart(name, price, qty = 1) {
  if (!name || !price || price <= 0) {
    showNotification('Invalid product', 'error');
    return;
  }
  const existing = TopHairCollections.cart.find(i => i.name === name);
  if (existing) {
    existing.quantity += qty;
    existing.totalPrice = existing.quantity * existing.unitPrice;
  } else {
    TopHairCollections.cart.push({
      id: Date.now(),
      name: name,
      unitPrice: price,
      quantity: qty,
      totalPrice: price * qty
    });
  }
  TopHairCollections.saveCartToStorage();
  displayCart();
  showNotification(`${name} added to cart!`, 'success');
}

function removeFromCart(id) {
  const idx = TopHairCollections.cart.findIndex(i => i.id === id);
  if (idx !== -1) {
    const name = TopHairCollections.cart[idx].name;
    TopHairCollections.cart.splice(idx, 1);
    TopHairCollections.saveCartToStorage();
    displayCart();
    showNotification(`${name} removed`, 'info');
  }
}

function displayCart() {
  const cartEl = document.getElementById('cartItems');
  const totalEl = document.getElementById('total');
  if (!cartEl || !totalEl) return;

  if (TopHairCollections.cart.length === 0) {
    cartEl.innerHTML = '<p class="cart-empty">Your cart is empty</p>';
    totalEl.textContent = TopHairCollections.config.currency + '0';
    return;
  }

  let html = '';
  let total = 0;
  TopHairCollections.cart.forEach(item => {
    total += item.totalPrice;
    html += `
      <div style="border-bottom:1px solid rgba(255,215,0,.2);padding:10px 0;margin:10px 0">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <div>
            <strong>${item.name}</strong><br>
            <small>${TopHairCollections.config.currency}${item.unitPrice.toLocaleString()} × ${item.quantity}</small>
          </div>
          <div style="display:flex;align-items:center;gap:8px">
            <strong>${TopHairCollections.config.currency}${item.totalPrice.toLocaleString()}</strong>
            <button onclick="removeFromCart(${item.id})" style="background:#e74c3c;color:#fff;border:none;border-radius:4px;padding:4px 8px;cursor:pointer;font-size:12px">✕</button>
          </div>
        </div>
      </div>`;
  });
  cartEl.innerHTML = html;
  totalEl.textContent = TopHairCollections.config.currency + total.toLocaleString();
}

function checkout() {
  if (TopHairCollections.cart.length === 0) {
    showNotification('Your cart is empty', 'error');
    return;
  }
  const total = TopHairCollections.cart.reduce((sum, item) => sum + item.totalPrice, 0);
  const message = `Order Total: ${TopHairCollections.config.currency}${total.toLocaleString()}\n\nYou will be redirected to complete your order.`;
  alert(message);
}

function payOnline() {
  if (TopHairCollections.cart.length === 0) {
    showNotification('Your cart is empty', 'error');
    return;
  }
  const total = TopHairCollections.cart.reduce((sum, item) => sum + item.totalPrice, 0);
  showNotification('Redirecting to Paystack...', 'info');
}

function trackOrder() {
  const code = document.getElementById('trackCode');
  const result = document.getElementById('trackResult');
  if (!code || !result) return;

  const val = code.value.trim();
  if (!val) {
    showNotification('Please enter a tracking code', 'error');
    return;
  }

  result.innerHTML = '<span style="color:#ff6bb8">🔄 Loading tracking info...</span>';

  setTimeout(() => {
    const statuses = [
      '📦 Order Confirmed',
      '🏭 Being Processed',
      '✅ Quality Checked',
      '🚚 Shipped & On The Way',
      '📍 Out for Delivery',
      '🎉 Delivered Successfully'
    ];
    const randomStatus = statuses[Math.floor(Math.random() * statuses.length)];
    result.innerHTML = `
      <div style="text-align:left;background:#fff;padding:15px;border-radius:8px;border-left:4px solid #ff6bb8;margin-top:10px">
        <p><strong>Tracking Code:</strong> ${val}</p>
        <p><strong>Status:</strong> ${randomStatus}</p>
        <p style="color:#999;font-size:12px">Last updated: ${new Date().toLocaleString()}</p>
      </div>`;
  }, 1500);
}

function performSearch() {
  const input = document.getElementById('productSearch');
  const items = document.querySelectorAll('.item');
  const noResults = document.getElementById('noResults');
  if (!input) return;

  const query = input.value.toLowerCase().trim();
  let found = 0;

  items.forEach(item => {
    const name = item.querySelector('h3')?.textContent.toLowerCase() || '';
    const desc = item.querySelector('p')?.textContent.toLowerCase() || '';
    const category = item.querySelector('.category-tag')?.textContent.toLowerCase() || '';

    if (name.includes(query) || desc.includes(query) || category.includes(query) || query === '') {
      item.style.display = '';
      found++;
    } else {
      item.style.display = 'none';
    }
  });

  if (found === 0 && noResults) {
    noResults.style.display = 'block';
  } else if (noResults) {
    noResults.style.display = 'none';
  }
}

function clearSearch() {
  const input = document.getElementById('productSearch');
  const items = document.querySelectorAll('.item');
  const noResults = document.getElementById('noResults');

  if (input) input.value = '';
  items.forEach(item => item.style.display = '');
  if (noResults) noResults.style.display = 'none';
}

function filterProducts(category) {
  const items = document.querySelectorAll('.item');
  const buttons = document.querySelectorAll('.filter-btn');

  buttons.forEach(btn => btn.classList.remove('active'));
  event.target.classList.add('active');

  items.forEach(item => {
    const cats = item.getAttribute('data-category') || '';
    if (category === 'all' || cats.includes(category)) {
      item.style.display = '';
    } else {
      item.style.display = 'none';
    }
  });
}

function showNotification(message, type = 'info') {
  const existing = document.querySelector('.notification');
  if (existing) existing.remove();

  const notification = document.createElement('div');
  notification.className = 'notification';
  notification.style.cssText = `
    position:fixed;bottom:20px;right:20px;padding:12px 20px;border-radius:8px;
    color:#fff;font-weight:600;z-index:9999;animation:slideIn .3s ease;
    font-family:var(--font-body);font-size:.9rem;box-shadow:0 4px 12px rgba(0,0,0,.15);
  `;

  const colors = { success: '#4CAF50', error: '#e74c3c', info: '#2196F3' };
  notification.style.background = colors[type] || colors.info;
  notification.textContent = message;

  document.body.appendChild(notification);
  setTimeout(() => {
    notification.style.animation = 'slideOut .3s ease forwards';
    setTimeout(() => notification.remove(), 300);
  }, 3000);
}

document.addEventListener('DOMContentLoaded', () => TopHairCollections.init());
